// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Superseded Frontier generations must be retired from disk: the service keeps the current generation and its direct
 * predecessor (needed by {@link LmdbStatisticsService#rollback()} and startup recovery), keeps every generation that a
 * query lease still references, and never touches files that belong to a generation newer than the current one (outputs
 * of an in-progress build are written under their final names long before they are published).
 */
class LmdbStatisticsGenerationRetirementTest {

	private static final int PROBE_SHARD = 9_000;

	@TempDir
	Path directory;

	private LmdbStatisticsService service;

	@AfterEach
	void closeService() {
		if (service != null) {
			service.close();
		}
	}

	@Test
	void publishingAThirdGenerationRetiresTheFirstManifestAndItsUnreferencedShards() throws Exception {
		service = openService();
		FrontierStatisticsManifest one = writeGeneration(1L, -1L, 7L, 41L);
		FrontierStatisticsManifest two = writeGeneration(2L, 1L, 8L, 82L);
		FrontierStatisticsManifest three = writeGeneration(3L, 2L, 9L, 123L);
		service.publish(one);
		service.publish(two);
		service.publish(three);

		assertFalse(Files.exists(manifestPath(1L)), "the manifest two generations back must be retired");
		for (Path shard : shardPaths(one)) {
			assertFalse(Files.exists(shard), () -> "unreferenced shard of a retired generation survived: " + shard);
		}
		assertTrue(Files.exists(manifestPath(2L)), "the direct predecessor manifest must be retained");
		assertTrue(Files.exists(manifestPath(3L)));
		for (Path shard : shardPaths(two)) {
			assertTrue(Files.exists(shard), () -> "predecessor shard must be retained: " + shard);
		}
		for (Path shard : shardPaths(three)) {
			assertTrue(Files.exists(shard), () -> "current shard must be retained: " + shard);
		}
		assertTrue(Files.exists(directory.resolve("CURRENT.fs2")));

		assertTrue(service.rollback(), "rollback to the retained predecessor must still work after retirement");
		assertEquals(2L, service.status().generationId());
		try (FrontierStatisticsLease lease = service.acquire(8L)) {
			assertEquals(82L, lease.shard(PROBE_SHARD).column(0).value(0L));
		}
	}

	@Test
	void leasedRetiredGenerationKeepsItsFilesUntilTheLeaseCloses() throws Exception {
		service = openService();
		FrontierStatisticsManifest one = writeGeneration(1L, -1L, 7L, 41L);
		service.publish(one);
		FrontierStatisticsLease oldLease = service.acquire(7L);
		assertTrue(oldLease.ready());
		service.publish(writeGeneration(2L, 1L, 8L, 82L));
		service.publish(writeGeneration(3L, 2L, 9L, 123L));

		assertTrue(Files.exists(manifestPath(1L)), "a leased generation must keep its manifest");
		for (Path shard : shardPaths(one)) {
			assertTrue(Files.exists(shard), () -> "a leased generation must keep its shards: " + shard);
		}
		assertEquals(41L, oldLease.shard(PROBE_SHARD).column(0).value(0L));

		oldLease.close();

		assertFalse(Files.exists(manifestPath(1L)), "closing the last lease must retire the generation");
		for (Path shard : shardPaths(one)) {
			assertFalse(Files.exists(shard), () -> "shard of a fully released generation survived: " + shard);
		}
		assertEquals(3L, service.status().generationId());
		try (FrontierStatisticsLease current = service.acquire(9L)) {
			assertEquals(123L, current.shard(PROBE_SHARD).column(0).value(0L));
		}
	}

	@Test
	void inProgressBuildOutputsSurviveRetirementTriggeredByALeaseRelease() throws Exception {
		service = openService();
		FrontierStatisticsManifest one = writeGeneration(1L, -1L, 7L, 41L);
		service.publish(one);
		FrontierStatisticsLease oldLease = service.acquire(7L);
		service.publish(writeGeneration(2L, 1L, 8L, 82L));
		service.publish(writeGeneration(3L, 2L, 9L, 123L));
		// A build in progress writes its shards under their final published names before the manifest exists.
		FrontierStatisticsManifest four = writeGeneration(4L, 3L, 10L, 164L);
		for (Path shard : shardPaths(four)) {
			assertTrue(Files.exists(shard));
		}

		oldLease.close();

		for (Path shard : shardPaths(one)) {
			assertFalse(Files.exists(shard), () -> "the released generation must be retired: " + shard);
		}
		for (Path shard : shardPaths(four)) {
			assertTrue(Files.exists(shard), () -> "retirement deleted the output of an in-progress build: " + shard);
		}
		service.publish(four);
		assertEquals(4L, service.status().generationId());
		try (FrontierStatisticsLease current = service.acquire(10L)) {
			assertEquals(164L, current.shard(PROBE_SHARD).column(0).value(0L));
		}
	}

	@Test
	void startupRetiresStaleGenerationsButKeepsCurrentAndPredecessor() throws Exception {
		FrontierStatisticsManifestStore store = new FrontierStatisticsManifestStore(directory,
				NioFrontierFileOps.INSTANCE);
		List<FrontierStatisticsManifest> generations = new ArrayList<>();
		for (long generation = 1L; generation <= 5L; generation++) {
			FrontierStatisticsManifest manifest = writeGeneration(generation, generation - 1L, 6L + generation,
					41L * generation);
			store.publish(manifest);
			generations.add(manifest);
		}
		for (long generation = 1L; generation <= 5L; generation++) {
			assertTrue(Files.exists(manifestPath(generation)), "precondition: bloated directory");
		}

		service = openService();

		assertEquals(FrontierStatisticsAvailability.READY, service.status().availability());
		assertEquals(5L, service.status().generationId());
		assertFalse(service.rebuildRequired(), "retirement is housekeeping, not a repair");
		for (long generation = 1L; generation <= 3L; generation++) {
			assertFalse(Files.exists(manifestPath(generation)), "stale manifest " + generation + " must be retired");
			for (Path shard : shardPaths(generations.get((int) generation - 1))) {
				assertFalse(Files.exists(shard), () -> "stale shard survived the startup sweep: " + shard);
			}
		}
		assertTrue(Files.exists(manifestPath(4L)));
		assertTrue(Files.exists(manifestPath(5L)));
		for (Path shard : shardPaths(generations.get(3))) {
			assertTrue(Files.exists(shard), () -> "predecessor shard must survive the startup sweep: " + shard);
		}
		for (Path shard : shardPaths(generations.get(4))) {
			assertTrue(Files.exists(shard), () -> "current shard must survive the startup sweep: " + shard);
		}
		assertTrue(service.rollback());
		assertEquals(4L, service.status().generationId());
		service.close();
		service = openService();
		assertEquals(FrontierStatisticsAvailability.READY, service.status().availability());
		assertEquals(4L, service.status().generationId());
	}

	@Test
	void retirementNeverTouchesTemporaryFilesOrNewerGenerations() throws Exception {
		service = openService();
		service.publish(writeGeneration(1L, -1L, 7L, 41L));
		Path interruptedShard = directory.resolve("generation-0000000000000000001-shard-00777.fs2s.tmp");
		Path interruptedManifest = directory.resolve("manifest-0000000000000000001.fs2m.tmp");
		Path futureShard = directory.resolve("generation-0000000000000000009-shard-00001.fs2s");
		Files.write(interruptedShard, new byte[] { 1 });
		Files.write(interruptedManifest, new byte[] { 2 });
		Files.write(futureShard, new byte[] { 3 });
		service.publish(writeGeneration(2L, 1L, 8L, 82L));
		service.publish(writeGeneration(3L, 2L, 9L, 123L));

		assertFalse(Files.exists(manifestPath(1L)));
		assertTrue(Files.exists(interruptedShard), "temporary artifacts are startup cleanup, never retirement");
		assertTrue(Files.exists(interruptedManifest), "temporary artifacts are startup cleanup, never retirement");
		assertTrue(Files.exists(futureShard), "files of a newer generation belong to a build in progress");
	}

	@Test
	void recoveryStillRollsBackToThePredecessorAfterRetirement() throws Exception {
		service = openService();
		service.publish(writeGeneration(1L, -1L, 7L, 41L));
		service.publish(writeGeneration(2L, 1L, 8L, 82L));
		FrontierStatisticsManifest three = writeGeneration(3L, 2L, 9L, 123L);
		service.publish(three);
		service.close();
		service = null;
		Path corruptShard = directory.resolve(three.shards()
				.stream()
				.filter(descriptor -> descriptor.shardId() == PROBE_SHARD)
				.findFirst()
				.orElseThrow()
				.fileName());
		Files.write(corruptShard, new byte[] { 0 });

		service = openService();

		assertEquals(FrontierStatisticsAvailability.READY, service.status().availability());
		assertEquals(2L, service.status().generationId(), "the retained predecessor must carry recovery");
		assertTrue(service.rebuildRequired());
		try (FrontierStatisticsLease lease = service.acquire(8L)) {
			assertEquals(82L, lease.shard(PROBE_SHARD).column(0).value(0L));
		}
	}

	private LmdbStatisticsService openService() throws IOException {
		return LmdbStatisticsService.open(directory,
				new FrontierStatisticsHeapGovernor(
						2L * 1024L * 1024L * 1024L,
						256L * 1024L * 1024L,
						512L * 1024L * 1024L,
						256L * 1024L * 1024L),
				128L * 1024L * 1024L * 1024L,
				60_000L,
				Runnable::run);
	}

	private Path manifestPath(long generationId) {
		return directory.resolve("manifest-%019d.fs2m".formatted(generationId));
	}

	private List<Path> shardPaths(FrontierStatisticsManifest manifest) {
		return manifest.shards().stream().map(descriptor -> directory.resolve(descriptor.fileName())).toList();
	}

	private FrontierStatisticsManifest writeGeneration(long generationId, long previousGenerationId, long epoch,
			long value) throws IOException {
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				32L * 1024L * 1024L, 64, 32, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				64L * 1024L * 1024L, 8L * 1024L * 1024L, 16L * 1024L * 1024L, 8L * 1024L * 1024L);
		FrontierStatisticsManifest core = FrontierStatisticsBuilder.build(
				directory, generationId, previousGenerationId, emptySnapshot(epoch), governor, config);
		String fileName = "generation-%019d-shard-%05d.fs2s".formatted(generationId, PROBE_SHARD);
		Path shardPath = directory.resolve(fileName);
		try (FrontierStatisticsShardWriter writer = new FrontierStatisticsShardWriter(
				shardPath, generationId, PROBE_SHARD, epoch, core.maximumTermId(), 1L)) {
			writer.addUnsignedColumn(0, new long[] { value });
			writer.finish();
		}
		FrontierStatisticsShardDescriptor descriptor = new FrontierStatisticsShardDescriptor(
				PROBE_SHARD, FrontierStatisticsTier.EXACT_AND_LINEAR, true, fileName, Files.size(shardPath), 1L);
		ArrayList<FrontierStatisticsShardDescriptor> descriptors = new ArrayList<>(core.shards());
		descriptors.add(descriptor);
		return new FrontierStatisticsManifest(
				core.generationId(), core.previousGenerationId(), core.baseEpoch(), core.coveredEpoch(),
				core.coveredSequence(), core.createdAtMillis(), core.maximumTermId(), descriptors);
	}

	private static FrontierSnapshotSource emptySnapshot(long epoch) {
		return new FrontierSnapshotSource() {
			@Override
			public long snapshotEpoch() {
				return epoch;
			}

			@Override
			public long rowCount(boolean explicit) {
				return 0L;
			}

			@Override
			public long scan(boolean explicit, RawQuadSink sink) {
				return 0L;
			}

			@Override
			public boolean contains(long subjectId, long predicateId, long objectId, long contextId,
					boolean explicit) {
				return false;
			}

			@Override
			public void close() {
			}
		};
	}
}
